window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c9b29126e13c1882"]={"versions": [{"id": "FIG-c9b29126e13c1882", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Zuordnung von AUTOSAR-RTE-Events im Kontext der Verhaltensmodellierung (<code>Behavior Modeling</code>). Es spezifiziert, wie RTE-Ereignisse Software-Komponenten und deren Verhaltensumgebung (<code>BM Software-Component</code>, <code>BM Environment</code>) zugeordnet werden, um Ausführungszeitpunkte von <code>RunnableEntity</code>-Instanzen auszulösen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Pakete / Modellbereiche (<code>from Behavior Modeling</code>):</strong>\n<ul class=\"fig-list\"><li><code>BM Software-Component</code>: Importiert die Entität <code>InternalBehavior::RunnableEntity</code>.\n</li><li><code>BM Environment</code>: Importiert spezialisierte RTE-Events (<code>TimingEvent</code>, <code>OperationInvokedEvent</code>, <code>DataReceivedEvent</code>, <code>AsynchronousServerCallReturnsEvent</code>, <code>DataSendCompletedEvent</code>) und referenziert die Basisklasse <code>RTEEvents::RTEEvent</code>.\n</li></ul>\n</li><li><strong>Entitäten (Metaklassen, je mit Stereotyp «Identifiable»):</strong>\n<ul class=\"fig-list\"><li><code>RTEEvents::RTEEvent</code>: Abstrakte Basisklasse für alle RTE-Ereignisse.\n</li><li><code>InternalBehavior::RunnableEntity</code>: Ausführbare Funktionseinheit innerhalb des internen Verhaltens einer Software-Komponente.\n</li></ul>\n</li><li><strong>Spezialisierte Klassen (<code>RTEEvents::*</code>, erben via Generalisierung von <code>RTEEvent</code>):</strong>\n<ul class=\"fig-list\"><li><code>ModeSwitchEvent</code>\n</li><li><code>TimingEvent</code>\n</li><li><code>OperationInvokedEvent</code>\n</li><li><code>DataReceivedEvent</code>\n</li><li><code>AsynchronousServerCallReturnsEvent</code>\n</li><li><code>DataSendCompletedEvent</code>\n</li><li><code>ExternalEvent</code>\n</li></ul>\n</li><li><strong>Beziehungen &amp; Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>RTEEvent</code> zu <code>RunnableEntity</code>: Unidirektionale Assoziation mit Rollenbezeichnung <code>+startOnEvent</code> und Kardinalität <code>0..1</code> an der <code>RunnableEntity</code>.\n</li><li>«import»-Abhängigkeiten von <code>BM Environment</code> zu:\n<ul class=\"fig-list\"><li><code>TimingEvent</code>\n</li><li><code>OperationInvokedEvent</code>\n</li><li><code>DataReceivedEvent</code>\n</li><li><code>AsynchronousServerCallReturnsEvent</code>\n</li><li><code>DataSendCompletedEvent</code>\n</li><li>gestrichelte Assoziation/Abhängigkeit zu <code>RTEEvent</code>\n</li></ul>\n</li><li>«import»-Abhängigkeit von <code>BM Software-Component</code> zu <code>RunnableEntity</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Trigger-Beziehung:</p>\n<ul class=\"fig-list\"><li>Das Eintreten eines konkreten <code>RTEEvent</code> aktiviert über die Relation <code>+startOnEvent</code> die zugeordnete <code>RunnableEntity</code> (Kardinalität <code>0..1</code>).\n</li><li>Die Ereignisse werden konzeptionell aus der Verhaltensumgebung (<code>BM Environment</code>) übermittelt (periodische Auslösung via <code>TimingEvent</code>, Empfang von Daten via <code>DataReceivedEvent</code>, Methodenaufrufe via <code>OperationInvokedEvent</code>, asynchrone Rückmeldungen via <code>AsynchronousServerCallReturnsEvent</code> oder Bestätigung von Datenübertragungen via <code>DataSendCompletedEvent</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein Notizkommentar im Diagramm schränkt die Gültigkeit bestimmter Subtypen für die Verhaltensmodellierung normativ ein:</p>\n<ul class=\"fig-list\"><li><code>ModeSwitchEvent is not supported because mode management must be clarified first.</code>\n</li><li><code>ExternalEvents are not supported, because there is currently no use case for it.</code>\n</li></ul>\n<p class=\"fig-p\">Werkzeuge und Generatoren für Verhaltensmodelle müssen diese Einschränkungen beachten: Lediglich die durch <code>BM Environment</code> importierten Ereignisse (<code>TimingEvent</code>, <code>OperationInvokedEvent</code>, <code>DataReceivedEvent</code>, <code>AsynchronousServerCallReturnsEvent</code>, <code>DataSendCompletedEvent</code>) stehen zur Aktivierung von Runnables im Verhaltensmodell zur Verfügung.</p>"}, {"id": "FIG-d308f66ff7f28b30", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Zuordnung von AUTOSAR-RTE-Events im Kontext der Verhaltensmodellierung (<code>Behavior Modeling</code>). Es spezifiziert, wie RTE-Ereignisse Software-Komponenten und deren Verhaltensumgebung (<code>BM Software-Component</code>, <code>BM Environment</code>) zugeordnet werden, um Ausführungszeitpunkte von <code>RunnableEntity</code>-Instanzen auszulösen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Pakete / Modellbereiche (<code>from Behavior Modeling</code>):</strong>\n<ul class=\"fig-list\"><li><code>BM Software-Component</code>: Importiert die Entität <code>InternalBehavior::RunnableEntity</code>.\n</li><li><code>BM Environment</code>: Importiert spezialisierte RTE-Events (<code>TimingEvent</code>, <code>OperationInvokedEvent</code>, <code>DataReceivedEvent</code>, <code>AsynchronousServerCallReturnsEvent</code>, <code>DataSendCompletedEvent</code>) und referenziert die Basisklasse <code>RTEEvents::RTEEvent</code>.\n</li></ul>\n</li><li><strong>Entitäten (Metaklassen, je mit Stereotyp «Identifiable»):</strong>\n<ul class=\"fig-list\"><li><code>RTEEvents::RTEEvent</code>: Abstrakte Basisklasse für alle RTE-Ereignisse.\n</li><li><code>InternalBehavior::RunnableEntity</code>: Ausführbare Funktionseinheit innerhalb des internen Verhaltens einer Software-Komponente.\n</li></ul>\n</li><li><strong>Spezialisierte Klassen (<code>RTEEvents::*</code>, erben via Generalisierung von <code>RTEEvent</code>):</strong>\n<ul class=\"fig-list\"><li><code>ModeSwitchEvent</code>\n</li><li><code>TimingEvent</code>\n</li><li><code>OperationInvokedEvent</code>\n</li><li><code>DataReceivedEvent</code>\n</li><li><code>AsynchronousServerCallReturnsEvent</code>\n</li><li><code>DataSendCompletedEvent</code>\n</li><li><code>ExternalEvent</code>\n</li></ul>\n</li><li><strong>Beziehungen &amp; Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>RTEEvent</code> zu <code>RunnableEntity</code>: Unidirektionale Assoziation mit Rollenbezeichnung <code>+startOnEvent</code> und Kardinalität <code>0..1</code> an der <code>RunnableEntity</code>.\n</li><li>«import»-Abhängigkeiten von <code>BM Environment</code> zu:\n<ul class=\"fig-list\"><li><code>TimingEvent</code>\n</li><li><code>OperationInvokedEvent</code>\n</li><li><code>DataReceivedEvent</code>\n</li><li><code>AsynchronousServerCallReturnsEvent</code>\n</li><li><code>DataSendCompletedEvent</code>\n</li><li>gestrichelte Assoziation/Abhängigkeit zu <code>RTEEvent</code>\n</li></ul>\n</li><li>«import»-Abhängigkeit von <code>BM Software-Component</code> zu <code>RunnableEntity</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine statische Trigger-Beziehung:</p>\n<ul class=\"fig-list\"><li>Das Eintreten eines konkreten <code>RTEEvent</code> aktiviert über die Relation <code>+startOnEvent</code> die zugeordnete <code>RunnableEntity</code> (Kardinalität <code>0..1</code>).\n</li><li>Die Ereignisse werden konzeptionell aus der Verhaltensumgebung (<code>BM Environment</code>) übermittelt (periodische Auslösung via <code>TimingEvent</code>, Empfang von Daten via <code>DataReceivedEvent</code>, Methodenaufrufe via <code>OperationInvokedEvent</code>, asynchrone Rückmeldungen via <code>AsynchronousServerCallReturnsEvent</code> oder Bestätigung von Datenübertragungen via <code>DataSendCompletedEvent</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein Notizkommentar im Diagramm schränkt die Gültigkeit bestimmter Subtypen für die Verhaltensmodellierung normativ ein:</p>\n<ul class=\"fig-list\"><li><code>ModeSwitchEvent is not supported because mode management must be clarified first.</code>\n</li><li><code>ExternalEvents are not supported, because there is currently no use case for it.</code>\n</li></ul>\n<p class=\"fig-p\">Werkzeuge und Generatoren für Verhaltensmodelle müssen diese Einschränkungen beachten: Lediglich die durch <code>BM Environment</code> importierten Ereignisse (<code>TimingEvent</code>, <code>OperationInvokedEvent</code>, <code>DataReceivedEvent</code>, <code>AsynchronousServerCallReturnsEvent</code>, <code>DataSendCompletedEvent</code>) stehen zur Aktivierung von Runnables im Verhaltensmodell zur Verfügung.</p>"}], "trans": [{"from": "FIG-c9b29126e13c1882", "to": "FIG-d308f66ff7f28b30", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
